export type PageViewEvent = {
  path: string
  timestamp: string
}

/**
 * Sends a page view event to the analytics service.
 */
export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (endpoint) {
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'page_view', ...event }),
    })
    return
  }

  // Fallback when no endpoint is configured (e.g. local development)
  console.info('[analytics] page_view', event)
}

